import { sql } from 'drizzle-orm';
import {
  bigint,
  boolean,
  check,
  doublePrecision,
  index,
  integer,
  jsonb,
  pgTable,
  primaryKey,
  smallint,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core';
import { uuidv7 } from 'uuidv7';

/*
 * Conventions
 *  - Primary keys: UUIDv7 generated by the application (time-ordered, safe to expose).
 *  - Timestamps: timestamptz, UTC.
 *  - Everything that lives in the game world carries `world_id`, even though
 *    there is a single shared world today.
 *  - JSONB only for data whose shape is expected to evolve (e.g. appearance,
 *    event payloads), never for data we need to join or constrain on.
 *  - Text enums are constrained in the application (zod); see DATABASE.md.
 */

const id = () =>
  uuid('id')
    .primaryKey()
    .$defaultFn(() => uuidv7());
const createdAt = () => timestamp('created_at', { withTimezone: true }).notNull().defaultNow();
const updatedAt = () =>
  timestamp('updated_at', { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());

// ---------------------------------------------------------------------------
// Accounts & sessions (out-of-game identity)
// ---------------------------------------------------------------------------
export const accounts = pgTable(
  'accounts',
  {
    id: id(),
    /** Stored lower-cased and trimmed. */
    email: text('email').notNull(),
    passwordHash: text('password_hash').notNull(),
    /** 'active' | 'suspended' | 'banned' */
    status: text('status').notNull().default('active'),
    lastLoginAt: timestamp('last_login_at', { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex('accounts_email_uq').on(t.email)],
);

export const sessions = pgTable(
  'sessions',
  {
    id: id(),
    accountId: uuid('account_id')
      .notNull()
      .references(() => accounts.id, { onDelete: 'cascade' }),
    /** SHA-256 of the opaque session token; the token itself is never stored. */
    tokenHash: text('token_hash').notNull(),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    lastSeenAt: timestamp('last_seen_at', { withTimezone: true }).notNull().defaultNow(),
    ip: text('ip'),
    userAgent: text('user_agent'),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex('sessions_token_hash_uq').on(t.tokenHash),
    index('sessions_account_idx').on(t.accountId),
    index('sessions_expires_idx').on(t.expiresAt),
  ],
);

// ---------------------------------------------------------------------------
// World
// ---------------------------------------------------------------------------
export const worlds = pgTable(
  'worlds',
  {
    id: id(),
    slug: text('slug').notNull(),
    name: text('name').notNull(),
    /** 'open' | 'maintenance' | 'closed' */
    status: text('status').notNull().default('open'),
    /** Monotonic simulation tick, advanced only by the world worker. */
    tick: bigint('tick', { mode: 'number' }).notNull().default(0),
    lastTickAt: timestamp('last_tick_at', { withTimezone: true }),
    /** Hex where new characters appear. */
    spawnQ: integer('spawn_q').notNull().default(0),
    spawnR: integer('spawn_r').notNull().default(0),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex('worlds_slug_uq').on(t.slug)],
);

// ---------------------------------------------------------------------------
// Characters (in-game identity). An account owns many; plays one at a time.
// ---------------------------------------------------------------------------
export const characters = pgTable(
  'characters',
  {
    id: id(),
    accountId: uuid('account_id')
      .notNull()
      .references(() => accounts.id, { onDelete: 'cascade' }),
    worldId: uuid('world_id')
      .notNull()
      .references(() => worlds.id, { onDelete: 'restrict' }),
    name: text('name').notNull(),
    /** Versioned JSON, see CharacterAppearance in @realms/shared. */
    appearance: jsonb('appearance').notNull(),
    /** Base attributes (D33): start at 5; creation points on top; equipment adds bonuses. */
    attrMight: smallint('attr_might').notNull().default(5),
    attrAgility: smallint('attr_agility').notNull().default(5),
    attrPrecision: smallint('attr_precision').notNull().default(5),
    attrEndurance: smallint('attr_endurance').notNull().default(5),
    attrIntellect: smallint('attr_intellect').notNull().default(5),
    attrWill: smallint('attr_will').notNull().default(5),
    /** Attribute points not yet distributed. */
    attributePoints: smallint('attribute_points').notNull().default(0),
    /** Per-character currency earned through activities. */
    reputation: bigint('reputation', { mode: 'number' }).notNull().default(0),
    /** Gold (request #50): from Rifts; spent in shops and at the blacksmith. */
    gold: bigint('gold', { mode: 'number' }).notNull().default(0),
    /** Request #59: city storage size (80; more can be unlocked later). */
    storageSlots: smallint('storage_slots').notNull().default(80),
    /** Axial hex coordinates of the character on the world map. */
    hexQ: integer('hex_q').notNull(),
    hexR: integer('hex_r').notNull(),
    /** Nation of origin (request #43): 'west' | 'east' | 'north'; null for older characters. */
    nation: text('nation'),
    /**
     * Action Points (request #43): the value at `ap_updated_at`; the current
     * value adds what regenerated since (game-core `currentAp`).
     */
    ap: doublePrecision('ap').notNull().default(120),
    apUpdatedAt: timestamp('ap_updated_at', { withTimezone: true }).notNull().defaultNow(),
    lastPlayedAt: timestamp('last_played_at', { withTimezone: true }),
    /** Soft delete: the world's history may still reference this character. */
    deletedAt: timestamp('deleted_at', { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index('characters_account_idx')
      .on(t.accountId)
      .where(sql`${t.deletedAt} is null`),
    // Case-insensitive unique name per world among living characters.
    uniqueIndex('characters_world_name_uq')
      .on(t.worldId, sql`lower(${t.name})`)
      .where(sql`${t.deletedAt} is null`),
    index('characters_world_hex_idx').on(t.worldId, t.hexQ, t.hexR),
  ],
);

// ---------------------------------------------------------------------------
// Items owned by characters. `item_def_id` points to a definition in
// @realms/game-core content. `quality` is durability (0 = broken).
// ---------------------------------------------------------------------------
export const items = pgTable(
  'items',
  {
    id: id(),
    characterId: uuid('character_id')
      .notNull()
      .references(() => characters.id, { onDelete: 'cascade' }),
    itemDefId: text('item_def_id').notNull(),
    quality: smallint('quality').notNull().default(100),
    /** Stack size: materials and consumables stack (request #33); gear is always 1. */
    quantity: integer('quantity').notNull().default(1),
    /** EquipSlot when equipped, null when in the inventory. */
    equippedSlot: text('equipped_slot'),
    /** In the character's city storage instead of the bag (request #50). */
    inStorage: boolean('in_storage').notNull().default(false),
    /**
     * Request #59: position in the bag (0 … 19) or the storage grid (0 …
     * storage_slots − 1); null for equipped items (and until it is placed).
     */
    slot: smallint('slot'),
    /** Where it came from: 'starter', 'drop', 'loot_room', 'secret_room', 'event', … */
    source: text('source').notNull().default('starter'),
    /** Weapons: upgrade level (+0, +1, …). Same type + level = same stats (request #31). */
    upgradeLevel: smallint('upgrade_level').notNull().default(0),
    /**
     * Gathered materials (request #52): grade 0 Poor … 4 Exceptional; null =
     * no grade. Stacks only join stacks of the same grade.
     */
    grade: smallint('grade'),
    /** Weapons: special properties (max 5), e.g. [{ "id": "keen" }]. */
    specials: jsonb('specials').notNull().default([]),
    /** Weapons: 2 rune slots, locked by default (Runemaster = future). */
    runeSlots: jsonb('rune_slots')
      .notNull()
      .default([
        { unlocked: false, runeId: null },
        { unlocked: false, runeId: null },
      ]),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index('items_character_idx').on(t.characterId),
    // At most one item per slot per character.
    uniqueIndex('items_character_slot_uq')
      .on(t.characterId, t.equippedSlot)
      .where(sql`${t.equippedSlot} is not null`),
    check('items_quality_range', sql`${t.quality} between 0 and 100`),
    check('items_upgrade_level_range', sql`${t.upgradeLevel} between 0 and 10`),
    check('items_quantity_positive', sql`${t.quantity} > 0`),
    check('items_grade_range', sql`${t.grade} between 0 and 4`),
  ],
);

// Profession Mastery per character (request #33, ranks from request #51). A
// row appears the first time a profession is practised; no row = Novice.
// The DB columns keep their first names: `level` holds the Mastery rank index
// (0 Novice … 5 Grandmaster) and `xp` the Mastery points towards the next rank.
export const characterProfessions = pgTable(
  'character_professions',
  {
    characterId: uuid('character_id')
      .notNull()
      .references(() => characters.id, { onDelete: 'cascade' }),
    /** Profession id in game-core content (`PROFESSIONS`). */
    professionId: text('profession_id').notNull(),
    rank: smallint('level').notNull().default(0),
    points: integer('xp').notNull().default(0),
    /** The profession can be practised again from this moment (activity time cost). */
    readyAt: timestamp('ready_at', { withTimezone: true }),
    /** Statistics shown on the profession screen and profile (request #51). */
    attempts: integer('attempts').notNull().default(0),
    successes: integer('successes').notNull().default(0),
    itemsMade: integer('items_made').notNull().default(0),
    updatedAt: updatedAt(),
  },
  (t) => [
    primaryKey({ columns: [t.characterId, t.professionId] }),
    check('character_professions_rank_range', sql`${t.rank} between 0 and 5`),
  ],
);

// Skills learned by a character (from books). Weapon abilities are not stored:
// they come from the equipped weapon. `loadout_slot` 0–7 = prepared for combat
// (request #39: 8 prepared skills); null = learned but not prepared.
export const characterSkills = pgTable(
  'character_skills',
  {
    characterId: uuid('character_id')
      .notNull()
      .references(() => characters.id, { onDelete: 'cascade' }),
    skillId: text('skill_id').notNull(),
    loadoutSlot: smallint('loadout_slot'),
    /** Skill level (request #50): reading the book again raises it (1 … SKILL_RULES.maxLevel). */
    level: smallint('level').notNull().default(1),
    learnedAt: timestamp('learned_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    primaryKey({ columns: [t.characterId, t.skillId] }),
    uniqueIndex('character_skills_loadout_uq')
      .on(t.characterId, t.loadoutSlot)
      .where(sql`${t.loadoutSlot} is not null`),
    check('character_skills_loadout_range', sql`${t.loadoutSlot} between 0 and 7`),
  ],
);

// ---------------------------------------------------------------------------
// Rift runs: one combat instance per run. The whole combat state (a JSON
// document produced by the game-core engine) is saved after every action, so a
// refresh, reconnect or deploy never loses a fight.
// ---------------------------------------------------------------------------
export const riftRuns = pgTable(
  'rift_runs',
  {
    id: id(),
    worldId: uuid('world_id')
      .notNull()
      .references(() => worlds.id, { onDelete: 'restrict' }),
    /** Rift definition id in game-core content. */
    riftId: text('rift_id').notNull(),
    /** 'active' | 'victory' | 'defeat' | 'abandoned' */
    status: text('status').notNull().default('active'),
    /** Rooms entered so far. */
    roomIndex: smallint('room_index').notNull().default(0),
    /** Run state (game-core RunState v2: map, party, current room, combat, votes). */
    state: jsonb('state').notNull(),
    /** Incremented on every saved action (optimistic concurrency / client sync). */
    version: integer('version').notNull().default(0),
    /** When the current decision (vote) or combat planning phase times out (60 s, D16). */
    turnDeadline: timestamp('turn_deadline', { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    endedAt: timestamp('ended_at', { withTimezone: true }),
  },
  (t) => [index('rift_runs_status_idx').on(t.status)],
);

export const riftRunParticipants = pgTable(
  'rift_run_participants',
  {
    runId: uuid('run_id')
      .notNull()
      .references(() => riftRuns.id, { onDelete: 'cascade' }),
    characterId: uuid('character_id')
      .notNull()
      .references(() => characters.id, { onDelete: 'cascade' }),
    accountId: uuid('account_id')
      .notNull()
      .references(() => accounts.id, { onDelete: 'cascade' }),
    /** Rewards or penalty applied to this character when the run ended (or when they left). */
    result: jsonb('result'),
    /** Set when the character left a group run early (A28). */
    leftAt: timestamp('left_at', { withTimezone: true }),
    joinedAt: timestamp('joined_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    primaryKey({ columns: [t.runId, t.characterId] }),
    index('rift_run_participants_character_idx').on(t.characterId),
  ],
);

// ---------------------------------------------------------------------------
// Friendships between characters (A25). One row per pair, ids ordered
// (character_a < character_b) so a pair can only exist once.
// ---------------------------------------------------------------------------
export const friendships = pgTable(
  'friendships',
  {
    characterA: uuid('character_a')
      .notNull()
      .references(() => characters.id, { onDelete: 'cascade' }),
    characterB: uuid('character_b')
      .notNull()
      .references(() => characters.id, { onDelete: 'cascade' }),
    /** 'pending' | 'accepted' */
    status: text('status').notNull().default('pending'),
    requestedBy: uuid('requested_by')
      .notNull()
      .references(() => characters.id, { onDelete: 'cascade' }),
    createdAt: createdAt(),
    acceptedAt: timestamp('accepted_at', { withTimezone: true }),
  },
  (t) => [
    primaryKey({ columns: [t.characterA, t.characterB] }),
    index('friendships_b_idx').on(t.characterB),
    check('friendships_ordered', sql`${t.characterA} < ${t.characterB}`),
  ],
);

// ---------------------------------------------------------------------------
// Rift lobbies: groups of up to 6 forming before a run.
// ---------------------------------------------------------------------------
export const riftLobbies = pgTable(
  'rift_lobbies',
  {
    id: id(),
    worldId: uuid('world_id')
      .notNull()
      .references(() => worlds.id, { onDelete: 'restrict' }),
    riftId: text('rift_id').notNull(),
    leaderCharacterId: uuid('leader_character_id')
      .notNull()
      .references(() => characters.id, { onDelete: 'cascade' }),
    /** 'public' (anyone can join) | 'private' (invite only) */
    visibility: text('visibility').notNull().default('public'),
    /** 'open' | 'started' | 'closed' */
    status: text('status').notNull().default('open'),
    runId: uuid('run_id').references(() => riftRuns.id, { onDelete: 'set null' }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index('rift_lobbies_status_idx').on(t.status, t.visibility)],
);

export const riftLobbyMembers = pgTable(
  'rift_lobby_members',
  {
    lobbyId: uuid('lobby_id')
      .notNull()
      .references(() => riftLobbies.id, { onDelete: 'cascade' }),
    characterId: uuid('character_id')
      .notNull()
      .references(() => characters.id, { onDelete: 'cascade' }),
    accountId: uuid('account_id')
      .notNull()
      .references(() => accounts.id, { onDelete: 'cascade' }),
    /** Formation slot 0–5 (0–2 front row, 3–5 back row). */
    slot: smallint('slot').notNull(),
    ready: boolean('ready').notNull().default(false),
    joinedAt: timestamp('joined_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    primaryKey({ columns: [t.lobbyId, t.characterId] }),
    uniqueIndex('rift_lobby_members_slot_uq').on(t.lobbyId, t.slot),
    index('rift_lobby_members_character_idx').on(t.characterId),
  ],
);

export const riftLobbyInvites = pgTable(
  'rift_lobby_invites',
  {
    lobbyId: uuid('lobby_id')
      .notNull()
      .references(() => riftLobbies.id, { onDelete: 'cascade' }),
    characterId: uuid('character_id')
      .notNull()
      .references(() => characters.id, { onDelete: 'cascade' }),
    invitedBy: uuid('invited_by')
      .notNull()
      .references(() => characters.id, { onDelete: 'cascade' }),
    createdAt: createdAt(),
  },
  (t) => [
    primaryKey({ columns: [t.lobbyId, t.characterId] }),
    index('rift_lobby_invites_character_idx').on(t.characterId),
  ],
);

// ---------------------------------------------------------------------------
// Custom content (admin tools, request #41): items and abilities made by the
// admin for testing. `definition` is validated by the zod schemas in
// @realms/shared (customItemInputSchema / customAbilityInputSchema) and loaded
// into the game-core content registry. Ids start with 'custom_'.
// ---------------------------------------------------------------------------
export const customContent = pgTable(
  'custom_content',
  {
    id: text('id').primaryKey(),
    /** 'item' | 'ability' */
    kind: text('kind').notNull(),
    definition: jsonb('definition').notNull(),
    createdBy: uuid('created_by').references(() => accounts.id, { onDelete: 'set null' }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    check('custom_content_kind_ck', sql`${t.kind} in ('item', 'ability')`),
    index('custom_content_kind_idx').on(t.kind, t.createdAt),
  ],
);

// ---------------------------------------------------------------------------
// Guilds (request #57): up to 16 members, emblem (icon + colour), reputation,
// gold bank, shared storage and a plot of land.
// ---------------------------------------------------------------------------
export const guilds = pgTable(
  'guilds',
  {
    id: id(),
    worldId: uuid('world_id')
      .notNull()
      .references(() => worlds.id, { onDelete: 'restrict' }),
    name: text('name').notNull(),
    icon: text('icon').notNull(),
    color: text('color').notNull(),
    leaderCharacterId: uuid('leader_character_id').references(() => characters.id, {
      onDelete: 'set null',
    }),
    reputation: bigint('reputation', { mode: 'number' }).notNull().default(0),
    gold: bigint('gold', { mode: 'number' }).notNull().default(0),
    /** The guild's land on the map (null = none yet). */
    landQ: integer('land_q'),
    landR: integer('land_r'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex('guilds_world_name_uq').on(t.worldId, sql`lower(${t.name})`),
    uniqueIndex('guilds_world_land_uq')
      .on(t.worldId, t.landQ, t.landR)
      .where(sql`${t.landQ} is not null`),
    check('guilds_gold_nonneg', sql`${t.gold} >= 0`),
  ],
);

export const guildMembers = pgTable(
  'guild_members',
  {
    /** A character is in at most one guild. */
    characterId: uuid('character_id')
      .primaryKey()
      .references(() => characters.id, { onDelete: 'cascade' }),
    guildId: uuid('guild_id')
      .notNull()
      .references(() => guilds.id, { onDelete: 'cascade' }),
    /** 'leader' | 'member'. */
    role: text('role').notNull().default('member'),
    joinedAt: timestamp('joined_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index('guild_members_guild_idx').on(t.guildId)],
);

export const guildInvites = pgTable(
  'guild_invites',
  {
    guildId: uuid('guild_id')
      .notNull()
      .references(() => guilds.id, { onDelete: 'cascade' }),
    characterId: uuid('character_id')
      .notNull()
      .references(() => characters.id, { onDelete: 'cascade' }),
    invitedBy: uuid('invited_by').references(() => characters.id, { onDelete: 'set null' }),
    createdAt: createdAt(),
  },
  (t) => [primaryKey({ columns: [t.guildId, t.characterId] })],
);

/** Guild storage: the same fields as `items`, owned by the guild. */
export const guildItems = pgTable(
  'guild_items',
  {
    id: id(),
    guildId: uuid('guild_id')
      .notNull()
      .references(() => guilds.id, { onDelete: 'cascade' }),
    itemDefId: text('item_def_id').notNull(),
    quality: smallint('quality').notNull().default(100),
    quantity: integer('quantity').notNull().default(1),
    upgradeLevel: smallint('upgrade_level').notNull().default(0),
    grade: smallint('grade'),
    specials: jsonb('specials').notNull().default([]),
    runeSlots: jsonb('rune_slots').notNull().default([]),
    source: text('source').notNull().default('guild'),
    depositedBy: uuid('deposited_by').references(() => characters.id, { onDelete: 'set null' }),
    createdAt: createdAt(),
  },
  (t) => [index('guild_items_guild_idx').on(t.guildId)],
);

// Player market (request #63): an item a player put up for sale in a city.
// It is only visible in that city's market and stays until bought or taken
// back. The item's fields are kept here while it is listed.
export const marketListings = pgTable(
  'market_listings',
  {
    id: id(),
    worldId: uuid('world_id')
      .notNull()
      .references(() => worlds.id, { onDelete: 'cascade' }),
    hexQ: integer('hex_q').notNull(),
    hexR: integer('hex_r').notNull(),
    sellerCharacterId: uuid('seller_character_id')
      .notNull()
      .references(() => characters.id, { onDelete: 'cascade' }),
    price: bigint('price', { mode: 'number' }).notNull(),
    itemDefId: text('item_def_id').notNull(),
    quality: smallint('quality').notNull().default(100),
    quantity: integer('quantity').notNull().default(1),
    upgradeLevel: smallint('upgrade_level').notNull().default(0),
    grade: smallint('grade'),
    specials: jsonb('specials').notNull().default([]),
    runeSlots: jsonb('rune_slots').notNull().default([]),
    source: text('source').notNull().default('market'),
    createdAt: createdAt(),
  },
  (t) => [
    index('market_listings_hex_idx').on(t.worldId, t.hexQ, t.hexR),
    index('market_listings_seller_idx').on(t.sellerCharacterId),
    check('market_listings_price_positive', sql`${t.price} > 0`),
  ],
);

// Profession jobs in real time (request #56): one per character. Inputs (and
// node charges) are taken at the start; the attempts are resolved when the job
// is read after `finishes_at`, and the summary is kept in `result` until the
// player dismisses it or starts another job.
export const professionJobs = pgTable(
  'profession_jobs',
  {
    id: id(),
    characterId: uuid('character_id')
      .notNull()
      .references(() => characters.id, { onDelete: 'cascade' }),
    professionId: text('profession_id').notNull(),
    activityId: text('activity_id').notNull(),
    count: smallint('count').notNull(),
    /** Gathering: the node used (charges reserved at the start) and its richness. */
    nodeQ: integer('node_q'),
    nodeR: integer('node_r'),
    nodeRichness: smallint('node_richness'),
    /** Tool tier and BASE-attribute bonus when the job started. */
    toolTier: smallint('tool_tier').notNull().default(0),
    attributeBonus: smallint('attribute_bonus').notNull().default(0),
    status: text('status').notNull().default('running'),
    result: jsonb('result'),
    startedAt: timestamp('started_at', { withTimezone: true }).notNull().defaultNow(),
    finishesAt: timestamp('finishes_at', { withTimezone: true }).notNull(),
  },
  (t) => [
    uniqueIndex('profession_jobs_character_uq').on(t.characterId),
    check('profession_jobs_count_range', sql`${t.count} between 1 and 50`),
  ],
);

// Resource nodes (request #52, professions phase 2). One per hex and gathering
// profession; a row appears the first time it is gathered from (no row = full).
// `amount` is the charges when `updated_at` was written; the current amount
// adds the regrowth since then (game-core `nodeAmount`), like AP.
export const resourceNodes = pgTable(
  'resource_nodes',
  {
    worldId: uuid('world_id')
      .notNull()
      .references(() => worlds.id, { onDelete: 'cascade' }),
    hexQ: integer('hex_q').notNull(),
    hexR: integer('hex_r').notNull(),
    professionId: text('profession_id').notNull(),
    amount: doublePrecision('amount').notNull(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [primaryKey({ columns: [t.worldId, t.hexQ, t.hexR, t.professionId] })],
);

// ---------------------------------------------------------------------------
// World boss (request #43): one per season, roaming the Riftlands with a huge
// shared HP pool. Every fight is an attempt; the leaderboard ranks parties by
// the damage they dealt.
// ---------------------------------------------------------------------------
export const worldBosses = pgTable(
  'world_bosses',
  {
    id: id(),
    worldId: uuid('world_id')
      .notNull()
      .references(() => worlds.id, { onDelete: 'cascade' }),
    season: integer('season').notNull(),
    hp: bigint('hp', { mode: 'number' }).notNull(),
    maxHp: bigint('max_hp', { mode: 'number' }).notNull(),
    hexQ: integer('hex_q').notNull(),
    hexR: integer('hex_r').notNull(),
    nextMoveAt: timestamp('next_move_at', { withTimezone: true }).notNull(),
    defeatedAt: timestamp('defeated_at', { withTimezone: true }),
    /** When the season's reward went to the top party (request #44); null = not yet. */
    rewardedAt: timestamp('rewarded_at', { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex('world_bosses_world_season_uq').on(t.worldId, t.season)],
);

export const worldBossAttempts = pgTable(
  'world_boss_attempts',
  {
    id: id(),
    bossId: uuid('boss_id')
      .notNull()
      .references(() => worldBosses.id, { onDelete: 'cascade' }),
    runId: uuid('run_id').references(() => riftRuns.id, { onDelete: 'set null' }),
    /** Sorted character ids of the party: the leaderboard groups by it. */
    partyKey: text('party_key').notNull(),
    /** [{ characterId, name }] at the time of the fight. */
    members: jsonb('members').notNull(),
    damage: bigint('damage', { mode: 'number' }).notNull().default(0),
    finishedAt: timestamp('finished_at', { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [
    index('world_boss_attempts_boss_idx').on(t.bossId, t.partyKey),
    index('world_boss_attempts_run_idx').on(t.runId),
  ],
);

// ---------------------------------------------------------------------------
// World events: append-only log of meaningful things that happened.
// Audit trail today; the backbone of world history / world-changing events later.
// ---------------------------------------------------------------------------
export const worldEvents = pgTable(
  'world_events',
  {
    id: id(),
    worldId: uuid('world_id')
      .notNull()
      .references(() => worlds.id, { onDelete: 'restrict' }),
    /** Dotted event type, e.g. 'character.created'. */
    type: text('type').notNull(),
    actorAccountId: uuid('actor_account_id').references(() => accounts.id, {
      onDelete: 'set null',
    }),
    actorCharacterId: uuid('actor_character_id').references(() => characters.id, {
      onDelete: 'set null',
    }),
    payload: jsonb('payload').notNull().default({}),
    createdAt: createdAt(),
  },
  (t) => [
    index('world_events_world_time_idx').on(t.worldId, t.createdAt),
    index('world_events_type_idx').on(t.type),
  ],
);

export type Account = typeof accounts.$inferSelect;
export type Session = typeof sessions.$inferSelect;
export type World = typeof worlds.$inferSelect;
export type Character = typeof characters.$inferSelect;
export type WorldEvent = typeof worldEvents.$inferSelect;
export type CustomContent = typeof customContent.$inferSelect;
export type Item = typeof items.$inferSelect;
export type CharacterSkill = typeof characterSkills.$inferSelect;
export type CharacterProfession = typeof characterProfessions.$inferSelect;
export type RiftRun = typeof riftRuns.$inferSelect;
export type RiftRunParticipant = typeof riftRunParticipants.$inferSelect;
export type Friendship = typeof friendships.$inferSelect;
export type RiftLobby = typeof riftLobbies.$inferSelect;
export type RiftLobbyMember = typeof riftLobbyMembers.$inferSelect;
